// Fleet Sensor Simulator (revised: per-type payloads + graph route-following)
//
// Each dispatchable vehicle idles at its home node until a dispatch command gives it a
// node route (the Actuator Controller sets v.route). It then interpolates along each
// graph edge at road speed until the route is exhausted, and parks at the destination.
// The bus ignores dispatch and runs a fixed loop of nodes. Payload fields depend on
// vehicleType and match schema/telemetry.schema.json. The graph comes from
// graph/melbourne.json via settings.js functionGlobalContext.

const G = global.get("melbourneGraph");
if (!G) {
    node.error("melbourneGraph missing from global context - check node-red/settings.js");
    return null;
}

const NODE = {};
for (const n of G.nodes) NODE[n.id] = n;

// Simulation time scale: each real-time tick advances vehicles by TICK_S simulated
// seconds. The reported `speed` stays a realistic km/h; only the position advance is
// fast-forwarded, so a cross-suburb dispatch completes in about a minute of wall clock
// instead of 20.
const TICK_S = 30;
const R_KM = 6371;
const rad = (d) => (d * Math.PI) / 180;
const rnd = (lo, hi) => lo + Math.random() * (hi - lo);
const round = (n, dp) => { const f = Math.pow(10, dp); return Math.round(n * f) / f; };

function havKm(a, b) {
    const dLa = rad(b.lat - a.lat), dLo = rad(b.lon - a.lon);
    const s = Math.sin(dLa / 2) ** 2 +
        Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLo / 2) ** 2;
    return 2 * R_KM * Math.asin(Math.sqrt(s));
}
function bearing(a, b) {
    const y = Math.sin(rad(b.lon - a.lon)) * Math.cos(rad(b.lat));
    const x = Math.cos(rad(a.lat)) * Math.sin(rad(b.lat)) -
        Math.sin(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.cos(rad(b.lon - a.lon));
    return (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
}

const SPEED = { sedan: [40, 58], van: [35, 50], bus: [20, 34] };  // km/h band per type

function mkVehicle(id, type, homeNode, busLoop) {
    const h = NODE[homeNode];
    return {
        vehicleID: id, vehicleType: type, homeNode: homeNode,
        nodeId: homeNode, route: [], edgeProgress: 0,
        lat: h.lat, lon: h.lon, heading: 0, speed: 0,
        batteryLevel: rnd(70, 100),
        currentState: type === "bus" ? "driving" : "parked",
        seatsOccupied: 0, doorsLocked: true, cargoLoadKg: 0,
        passengerCount: type === "bus" ? Math.round(rnd(5, 25)) : 0,
        rampDeployed: false,
        busLoop: busLoop || null, busLoopIdx: 0
    };
}

let fleet = flow.get("fleet");
if (!fleet) {
    fleet = [
        mkVehicle("TAXI-001", "sedan", 0, null),   // home Melbourne CBD
        mkVehicle("TAXI-002", "van", 18, null),     // home Sunshine
        mkVehicle("TAXI-003", "bus", 13, [13, 14, 16, 13])  // fixed loop Boxhill-Camberwell-Burwood
    ];
}

const now = Date.now();
const out = [];

for (const v of fleet) {
    // bus: keep its route topped up from the loop, skipping a zero-length hop
    if (v.vehicleType === "bus" && v.route.length === 0) {
        v.busLoopIdx = (v.busLoopIdx + 1) % v.busLoop.length;
        if (v.busLoop[v.busLoopIdx] === v.nodeId) {
            v.busLoopIdx = (v.busLoopIdx + 1) % v.busLoop.length;
        }
        v.route = [v.busLoop[v.busLoopIdx]];
    }

    v.doorState = { front: "closed", middle: "closed", slidingLeft: "closed", rear: "closed" };
    v.rampDeployed = false;
    const driving = v.route.length > 0;

    if (driving) {
        v.currentState = "driving";
        v.speed = round(rnd(SPEED[v.vehicleType][0], SPEED[v.vehicleType][1]), 1);
        const from = NODE[v.nodeId], to = NODE[v.route[0]];
        const edgeKm = Math.max(havKm(from, to), 0.001);
        v.edgeProgress += ((v.speed / 3600) * TICK_S) / edgeKm;

        if (v.edgeProgress >= 1) {
            v.nodeId = v.route.shift();
            v.edgeProgress = 0;
            const at = NODE[v.nodeId];
            v.lat = at.lat; v.lon = at.lon;
            if (v.vehicleType === "bus") {
                v.doorState.front = "open"; v.doorState.middle = "open";
                v.passengerCount = Math.min(40, Math.max(0, v.passengerCount + Math.round(rnd(-6, 8))));
                v.rampDeployed = Math.random() < 0.15;
            }
            if (v.route.length === 0 && v.vehicleType !== "bus") {
                v.currentState = "parked"; v.speed = 0;   // arrived at the pickup node
            } else {
                const nxt = NODE[v.route.length ? v.route[0] : v.nodeId];
                v.heading = round(bearing(at, nxt), 1);
            }
        } else {
            v.lat = from.lat + (to.lat - from.lat) * v.edgeProgress;
            v.lon = from.lon + (to.lon - from.lon) * v.edgeProgress;
            v.heading = round(bearing(from, to), 1);
        }
        v.batteryLevel = Math.max(0, v.batteryLevel - (v.vehicleType === "bus" ? 0.06 : 0.05));
    } else {
        const at = NODE[v.nodeId];
        v.lat = at.lat; v.lon = at.lon; v.speed = 0;
        if (v.batteryLevel < 40) {
            v.currentState = "charging";
            v.batteryLevel = Math.min(100, v.batteryLevel + 0.3);
        } else {
            v.currentState = "parked";
            v.batteryLevel = Math.max(0, v.batteryLevel - 0.003);
        }
        v.seatsOccupied = 0; v.cargoLoadKg = 0;
    }

    out.push({ topic: "fleet/" + v.vehicleID + "/telemetry", payload: buildPayload(v, now) });
}

flow.set("fleet", fleet);
return [out];

function occ(v, seatsTotal) {
    return {
        seatsTotal: seatsTotal,
        seatsOccupied: v.seatsOccupied,
        seatWeightKg: round(v.seatsOccupied * rnd(62, 82), 1)
    };
}

function buildPayload(v, ts) {
    const p = {
        vehicleID: v.vehicleID,
        vehicleType: v.vehicleType,
        coordinates: { lat: round(v.lat, 6), lon: round(v.lon, 6) },
        heading: round(v.heading, 1),
        speed: round(v.speed, 2),
        batteryLevel: round(v.batteryLevel, 2),
        currentState: v.currentState,
        timestamp: ts
    };
    if (v.vehicleType === "sedan") {
        p.occupancy = occ(v, 4);
        p.doorsLocked = v.doorsLocked;
    } else if (v.vehicleType === "van") {
        p.occupancy = occ(v, 7);
        p.doorState = { front: v.doorState.front, slidingLeft: v.doorState.slidingLeft, rear: v.doorState.rear };
        p.cargoLoadKg = round(v.cargoLoadKg, 1);
    } else {
        p.passengerCount = v.passengerCount;
        p.passengerCapacity = 40;
        p.doorState = { front: v.doorState.front, middle: v.doorState.middle, rear: v.doorState.rear };
        p.wheelchairRampDeployed = v.rampDeployed;
        p.nextStopId = v.route.length ? v.route[0] : v.nodeId;
    }
    return p;
}

// Edge Filter
// ROADMAP Week 2: "drop a reading if parked and GPS delta < 0.0001 degrees".
// A stationary vehicle (parked or charging) that has not moved since its last forwarded
// packet is suppressed - EXCEPT a heartbeat packet gets through every HEARTBEAT_MS so the
// Telemetry service (and the Dispatch service that reads it) always has a recent position
// and battery level for an idle-but-available vehicle.
// Output 1: forwarded. Output 2: suppressed (debug only).

const GPS_EPSILON = 0.0001;
const HEARTBEAT_MS = 20000;
const p = msg.payload;
const now = Date.now();

const lastSent = flow.get("lastSent") || {};
const prev = lastSent[p.vehicleID];

const stationary = p.currentState === "parked" || p.currentState === "charging";
const gpsUnchanged = !!prev
    && Math.abs(p.coordinates.lat - prev.lat) < GPS_EPSILON
    && Math.abs(p.coordinates.lon - prev.lon) < GPS_EPSILON;
const withinHeartbeat = !!prev && (now - prev.at) < HEARTBEAT_MS;

if (stationary && gpsUnchanged && withinHeartbeat) {
    msg.suppressedReason = "stationary and GPS delta < " + GPS_EPSILON;
    return [null, msg];
}

lastSent[p.vehicleID] = { lat: p.coordinates.lat, lon: p.coordinates.lon, at: now };
flow.set("lastSent", lastSent);
return [msg, null];

// Actuator Controller (revised: adopt the graph route from a dispatch command)
//
// Commands arrive on fleet/+/command from the Week 6 Dispatch service, or from the manual
// inject nodes here. Payload: { vehicleID, command, route?, passengers? }. command is one
// of dispatch, stop, lock_doors, unlock_doors.
//   dispatch : take on the node-id route (from A* in the Dispatch service) and board
//              passengers; the simulator drives it next tick.

const cmd = msg.payload || {};
const fleet = flow.get("fleet") || [];
const v = fleet.find((x) => x.vehicleID === cmd.vehicleID);

if (!v) {
    msg.topic = "fleet/actuator/error";
    msg.payload = { error: "unknown vehicleID", received: cmd };
    return msg;
}

let action;
switch (cmd.command) {
    case "dispatch": {
        const route = Array.isArray(cmd.route) ? cmd.route.slice() : [];
        if (route.length && route[0] === v.nodeId) route.shift();
        v.route = route;
        v.edgeProgress = 0;
        const seats = v.vehicleType === "van" ? 7 : 4;
        v.seatsOccupied = Math.max(1, Math.min(seats, cmd.passengers || 1));
        if (v.vehicleType === "van") v.cargoLoadKg = Math.round(Math.random() * 40);
        action = "motor controller engaged - dispatched over " + (v.route.length + 1) + " nodes";
        break;
    }
    case "stop":
        v.route = []; v.speed = 0; v.currentState = "parked"; v.seatsOccupied = 0;
        action = "motor controller disengaged - vehicle stopped";
        break;
    case "lock_doors":
        v.doorsLocked = true;
        action = "door lock actuator - doors locked";
        break;
    case "unlock_doors":
        v.doorsLocked = false;
        action = "door lock actuator - doors unlocked";
        break;
    default:
        action = 'no actuator mapped for command "' + cmd.command + '"';
}

flow.set("fleet", fleet);
msg.topic = "fleet/" + v.vehicleID + "/actuator";
msg.payload = {
    vehicleID: v.vehicleID,
    command: cmd.command,
    action: action,
    actuatorState: {
        route: v.route,
        currentState: v.currentState,
        doorsLocked: v.doorsLocked,
        seatsOccupied: v.seatsOccupied
    },
    timestamp: Date.now()
};
return msg;
